        Self::clear_current();
        if let Err(err) = lock_unpoisoned(&shared).finish(error, summary) {
            warn!("history: could not finish the operation record: {err:#}");
        }
    }

    fn clear_current() {
        *lock_unpoisoned(&CURRENT) = None;
